import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY") || Deno.env.get("GOOGLE_GEMINI_API_KEY") || "";
const GEMINI_MODEL = "gemini-1.5-flash";

function corsHeaders(origin: string | null) {
  return {
    "Access-Control-Allow-Origin": origin || "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Credentials": "true",
  };
}

function stripBase64Prefix(b64: string): { data: string; mimeType: string } {
  const mimeMatch = b64.match(/^data:(image\/[a-z]+);base64,/);
  const mimeType = mimeMatch ? mimeMatch[1] : "image/jpeg";
  const data = b64.replace(/^data:image\/[a-z]+;base64,/, "");
  return { data, mimeType };
}

Deno.serve(async (req: Request) => {
  const origin = req.headers.get("origin");
  const headers = corsHeaders(origin);

  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...headers, "Content-Type": "application/json" },
    });
  }

  try {
    const body = await req.json();
    const { main_image, comparison_image_1, comparison_image_2 } = body;

    if (!main_image || !comparison_image_1 || !comparison_image_2) {
      return new Response(
        JSON.stringify({ error: "main_image, comparison_image_1, and comparison_image_2 are required" }),
        { status: 400, headers: { ...headers, "Content-Type": "application/json" } }
      );
    }

    if (!GEMINI_API_KEY) {
      return new Response(JSON.stringify({ error: "GEMINI_API_KEY not configured" }), {
        status: 500,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    const main = stripBase64Prefix(main_image);
    const cmp1 = stripBase64Prefix(comparison_image_1);
    const cmp2 = stripBase64Prefix(comparison_image_2);

    const prompt = `Sei un esperto di somiglianza facciale. Ti vengono fornite tre foto:
- FOTO PRINCIPALE: la prima immagine
- FOTO 1: la seconda immagine
- FOTO 2: la terza immagine

Il tuo compito è determinare quale tra FOTO 1 e FOTO 2 somiglia di più alla FOTO PRINCIPALE, analizzando i lineamenti del viso: struttura ossea, occhi, naso, bocca, mascella, proporzioni generali e caratteristiche distintive.

Rispondi SOLO con un oggetto JSON puro (nessun markdown, nessun blocco di codice), con questa struttura esatta:
{
  "winner": 1,
  "similarity_1": 78,
  "similarity_2": 45,
  "explanation": "Breve spiegazione in italiano del perché il vincitore è stato scelto, citando i lineamenti specifici."
}

Regole:
- "winner" deve essere 1 o 2 (quale foto somiglia di più alla FOTO PRINCIPALE)
- "similarity_1" è un intero da 0 a 100 che indica la percentuale di somiglianza tra FOTO 1 e FOTO PRINCIPALE
- "similarity_2" è un intero da 0 a 100 che indica la percentuale di somiglianza tra FOTO 2 e FOTO PRINCIPALE
- "explanation" deve essere in italiano, 1-3 frasi, specifica sui lineamenti facciali
- Restituisci SOLO il JSON grezzo, nessun altro testo`;

    const geminiPayload = {
      contents: [
        {
          parts: [
            {
              inline_data: {
                mime_type: main.mimeType,
                data: main.data,
              },
            },
            {
              inline_data: {
                mime_type: cmp1.mimeType,
                data: cmp1.data,
              },
            },
            {
              inline_data: {
                mime_type: cmp2.mimeType,
                data: cmp2.data,
              },
            },
            { text: prompt },
          ],
        },
      ],
      generationConfig: {
        temperature: 0.4,
        maxOutputTokens: 512,
      },
    };

    const geminiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${GEMINI_API_KEY}`;

    const geminiRes = await fetch(geminiUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(geminiPayload),
    });

    if (!geminiRes.ok) {
      const errText = await geminiRes.text();
      console.error("[compare] Gemini API error:", geminiRes.status, errText);
      return new Response(
        JSON.stringify({ error: `Gemini API error: ${geminiRes.status}`, detail: errText }),
        { status: 502, headers: { ...headers, "Content-Type": "application/json" } }
      );
    }

    const geminiData = await geminiRes.json();
    const rawText: string = geminiData?.candidates?.[0]?.content?.parts?.[0]?.text || "";

    let parsed: { winner: number; similarity_1: number; similarity_2: number; explanation: string };
    try {
      const cleaned = rawText.replace(/```json\s*/gi, "").replace(/```\s*/gi, "").trim();
      parsed = JSON.parse(cleaned);
    } catch (_) {
      console.error("[compare] Failed to parse Gemini response:", rawText);
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          parsed = JSON.parse(jsonMatch[0]);
        } catch (_) {
          return new Response(
            JSON.stringify({ error: "Failed to parse AI response", raw: rawText }),
            { status: 500, headers: { ...headers, "Content-Type": "application/json" } }
          );
        }
      } else {
        return new Response(
          JSON.stringify({ error: "Failed to parse AI response", raw: rawText }),
          { status: 500, headers: { ...headers, "Content-Type": "application/json" } }
        );
      }
    }

    const winner = parsed.winner === 1 || parsed.winner === 2 ? parsed.winner : 1;
    const similarity_1 = Math.min(100, Math.max(0, Math.round(Number(parsed.similarity_1) || 0)));
    const similarity_2 = Math.min(100, Math.max(0, Math.round(Number(parsed.similarity_2) || 0)));
    const explanation = String(parsed.explanation || "");

    return new Response(
      JSON.stringify({ winner, similarity_1, similarity_2, explanation }),
      { status: 200, headers: { ...headers, "Content-Type": "application/json" } }
    );
  } catch (err: any) {
    console.error("[compare] Unexpected error:", err);
    return new Response(
      JSON.stringify({ error: err.message || "Internal server error" }),
      { status: 500, headers: { ...headers, "Content-Type": "application/json" } }
    );
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;

function corsHeaders(origin: string | null) {
  return {
    "Access-Control-Allow-Origin": origin || "*",
    "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Credentials": "true",
  };
}

// Extract user_id from the Authorization header.
// Supports both Supabase JWT (anon/user) and Better Auth session tokens.
async function getUserId(req: Request): Promise<string | null> {
  const authHeader = req.headers.get("authorization") || req.headers.get("Authorization");
  if (!authHeader) return null;

  const token = authHeader.replace(/^Bearer\s+/i, "");

  // Try Supabase JWT first
  try {
    const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      global: { headers: { Authorization: `Bearer ${token}` } },
    });
    const { data: { user }, error } = await supabase.auth.getUser();
    if (!error && user) return user.id;
  } catch (_) {}

  // Fall back: decode JWT payload if possible
  try {
    const parts = token.split(".");
    if (parts.length === 3) {
      const payload = JSON.parse(atob(parts[1]));
      if (payload.sub) return payload.sub;
      if (payload.userId) return payload.userId;
      if (payload.id) return payload.id;
    }
  } catch (_) {}

  // Last resort: use the raw token as user_id (works for opaque session tokens)
  return token || null;
}

Deno.serve(async (req: Request) => {
  const origin = req.headers.get("origin");
  const headers = corsHeaders(origin);

  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers });
  }

  const url = new URL(req.url);
  // Path: /comparisons or /comparisons/:id
  const pathParts = url.pathname.replace(/^\/comparisons\/?/, "").split("/").filter(Boolean);
  const id = pathParts[0] || null;

  const userId = await getUserId(req);
  if (!userId) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...headers, "Content-Type": "application/json" },
    });
  }

  // Use service role to bypass RLS — we enforce ownership manually
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    // GET /comparisons — list user's history
    if (req.method === "GET" && !id) {
      const { data, error } = await supabase
        .from("face_comparisons")
        .select("*")
        .eq("user_id", userId)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return new Response(JSON.stringify({ comparisons: data }), {
        status: 200,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // POST /comparisons — save a comparison result
    // Body: { image_url?: string, result: { winner, similarity_1, similarity_2, explanation } }
    if (req.method === "POST" && !id) {
      const body = await req.json();
      const { image_url, result } = body;

      // Validate result shape
      if (
        !result ||
        (result.winner !== 1 && result.winner !== 2) ||
        typeof result.similarity_1 !== "number" ||
        typeof result.similarity_2 !== "number" ||
        typeof result.explanation !== "string"
      ) {
        return new Response(
          JSON.stringify({
            error: "result must contain: winner (1|2), similarity_1 (number), similarity_2 (number), explanation (string)",
          }),
          { status: 400, headers: { ...headers, "Content-Type": "application/json" } }
        );
      }

      const normalizedResult = {
        winner: result.winner as 1 | 2,
        similarity_1: Math.min(100, Math.max(0, Math.round(result.similarity_1))),
        similarity_2: Math.min(100, Math.max(0, Math.round(result.similarity_2))),
        explanation: String(result.explanation),
      };

      const { data, error } = await supabase
        .from("face_comparisons")
        .insert({ user_id: userId, image_url: image_url || null, result: normalizedResult })
        .select()
        .single();

      if (error) throw error;
      return new Response(JSON.stringify(data), {
        status: 201,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    // DELETE /comparisons/:id — delete with ownership check
    if (req.method === "DELETE" && id) {
      const { data: existing, error: fetchError } = await supabase
        .from("face_comparisons")
        .select("id, user_id")
        .eq("id", id)
        .single();

      if (fetchError || !existing) {
        return new Response(JSON.stringify({ error: "Not found" }), {
          status: 404,
          headers: { ...headers, "Content-Type": "application/json" },
        });
      }

      if (existing.user_id !== userId) {
        return new Response(JSON.stringify({ error: "Forbidden" }), {
          status: 403,
          headers: { ...headers, "Content-Type": "application/json" },
        });
      }

      const { error: deleteError } = await supabase
        .from("face_comparisons")
        .delete()
        .eq("id", id);

      if (deleteError) throw deleteError;
      return new Response(JSON.stringify({ success: true }), {
        status: 200,
        headers: { ...headers, "Content-Type": "application/json" },
      });
    }

    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...headers, "Content-Type": "application/json" },
    });
  } catch (err: any) {
    console.error("[comparisons] Error:", err);
    return new Response(JSON.stringify({ error: err.message || "Internal server error" }), {
      status: 500,
      headers: { ...headers, "Content-Type": "application/json" },
    });
  }
});

